(()=>{'use strict';const TEAM_URL='ffws-br-2026-s2/teams.json?v=20260729-current-nav-v2',PLAYER_URL='ffws-br-2026-s2/players.json?v=20260729-current-nav-v2';const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase(),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));let teams=[],players=[],teamsPromise=null,playersPromise=null;function loadTeams(){if(teams.length)return Promise.resolve(teams);if(teamsPromise)return teamsPromise;teamsPromise=fetch(TEAM_URL,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status))).then(t=>{teams=t.teams||[];window.CFF_CURRENT_SEASON_TEAMS=teams;patchSearch();renderTeamNav();return teams}).catch(()=>[]);return teamsPromise}function loadPlayers(){if(players.length)return Promise.resolve(players);if(playersPromise)return playersPromise;playersPromise=fetch(PLAYER_URL,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status))).then(p=>{players=p.players||[];window.CFF_CURRENT_SEASON_PLAYERS=players;patchSearch();refreshOpenSearch();return players}).catch(()=>[]);return playersPromise}window.openCurrentSeasonTeam=name=>location.href=`equipe.html?time=${encodeURIComponent(name)}`;window.openCurrentSeasonPlayer=(name,team='')=>location.href=`jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(team)}`;function renderTeamNav(){const root=document.getElementById('nav-desktop-teams');if(!root||!teams.length)return;root.innerHTML=teams.map(t=>`<button class="nav-team-logo-btn" onclick="openCurrentSeasonTeam('${String(t.name).replace(/'/g,"\\'")}')" title="${esc(t.name)}"><img src="${esc(t.logo||'escudo.webp')}" alt="${esc(t.name)}" onerror="this.src='escudo.webp'"></button>`).join('')}function patchMobile(){window.mobileTabClick=function(key,button){const map={tabela:'ffws-br-s2-classificatoria',final:'ffws-br-s2-final',mvp:'ffws-br-s2-mvp',equipes:'ffws-br-s2-equipes'};if(typeof window.navigate==='function')window.navigate(map[key]||key);document.querySelectorAll('.nav-mobile-tab').forEach(el=>el.classList.remove('active'));button?.classList.add('active')}}function patchSearch(){if(typeof window.navBuildTeamSearchPool==='function'&&!window.navBuildTeamSearchPool.__s2){const original=window.navBuildTeamSearchPool;const wrapped=function(){const base=original()||[],map=new Map(base.map(x=>[norm(x.name||x.title),x]));teams.forEach(t=>map.set(norm(t.name),{type:'s2-team',name:t.name,title:t.name,sub:'WB 2026 S2',img:t.logo||'escudo.webp',haystack:`${t.name} ${t.abbreviation||''} WB 2026 S2`,score:0,isWB:true}));return[...map.values()]};wrapped.__s2=true;window.navBuildTeamSearchPool=wrapped;try{navBuildTeamSearchPool=wrapped}catch(_){}}if(typeof window.navBuildPeopleSearchPool==='function'&&!window.navBuildPeopleSearchPool.__s2){const original=window.navBuildPeopleSearchPool;const wrapped=function(){const base=original()||[],map=new Map(base.map(x=>[norm(x.name),x]));players.forEach(p=>map.set(norm(p.name),{type:'s2-player',name:`${p.name}|||${p.team}`,originalName:p.sourceName||p.name,title:p.name,sub:`${p.team} • WB 2026 S2`,img:'silhueta.webp',priority:10,haystack:`${p.name} ${(p.aliases||[]).join(' ')} ${p.team} ${p.role||''} WB 2026 S2`}));return[...map.values()]};wrapped.__s2=true;window.navBuildPeopleSearchPool=wrapped;try{navBuildPeopleSearchPool=wrapped}catch(_){}}const originalSelect=window.selectSearchResult||((typeof selectSearchResult==='function')?selectSearchResult:null);if(originalSelect&&!originalSelect.__s2){const wrapped=function(type,name){if(type==='s2-team'){window.navCloseSearchUI?.();return window.openCurrentSeasonTeam(name)}if(type==='s2-player'){window.navCloseSearchUI?.();const [player,team]=String(name||'').split('|||');return window.openCurrentSeasonPlayer(player,team)}return originalSelect.call(window,type,name)};wrapped.__s2=true;window.selectSearchResult=wrapped;try{selectSearchResult=wrapped}catch(_){}}}function refreshOpenSearch(){const desktop=document.getElementById('global-search-desktop'),mobile=document.getElementById('global-search-mobile');if(desktop?.value?.trim().length>=2&&typeof window.handleGlobalSearchFrom==='function')window.handleGlobalSearchFrom('desktop');if(mobile?.value?.trim().length>=2&&typeof window.handleGlobalSearchFrom==='function')window.handleGlobalSearchFrom('mobile')}function bindSearchLazy(){['global-search-desktop','global-search-mobile','global-search-page-input'].forEach(id=>{const el=document.getElementById(id);if(!el||el.dataset.s2LazyBound)return;el.dataset.s2LazyBound='1';el.addEventListener('focus',loadPlayers,{once:true});el.addEventListener('input',loadPlayers,{once:true})})}function boot(){patchMobile();loadTeams();bindSearchLazy();[500,1600,3200].forEach(ms=>setTimeout(()=>{patchMobile();patchSearch();renderTeamNav();bindSearchLazy()},ms));(window.requestIdleCallback||function(cb){return setTimeout(cb,5000)})(()=>loadPlayers(),{timeout:7000})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();
